package com.tenora365.service;
import org.springframework.beans.factory.annotation.Value;import org.springframework.mail.SimpleMailMessage;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.util.*;
@Service public class NotificationService{@Value("${app.demo:false}")boolean demo;final JavaMailSender mail;final String host;final String user;NotificationService(JavaMailSender m,@Value("${spring.mail.host:}")String h,@Value("${spring.mail.username:}")String u){mail=m;host=h;user=u;}public String email(String to,String subject,String body){if(demo)return "DEMO_DISABLED";if(host==null||host.isBlank()||user==null||user.isBlank()){System.out.println("EMAIL NOT SENT (SMTP not configured): "+to+" / "+subject);return "LOGGED";}SimpleMailMessage x=new SimpleMailMessage();x.setFrom(user);x.setTo(to);x.setSubject(subject);x.setText(body);mail.send(x);return "SENT";}public String webhook(String url,Object payload){if(demo)return "DEMO_DISABLED";if(url==null||url.isBlank()){System.out.println("WEBHOOK NOT SENT (provider URL not configured): "+payload);return "LOGGED";}RestClient.create().post().uri(url).body(payload).retrieve().toBodilessEntity();return "SENT";}}
